<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {ElMessageBox} from 'element-plus'
import {catalogStyleIdentities,previewCatalogIdentities,saveCatalogIdentities} from '@/api/modules/partnerCatalog'
import {newRequestId} from '@/api/modules/partner'
import type {CatalogCodeOption,CatalogIdentityPreview,CatalogStyle} from '@/types/partnerCatalog'
import {partnerError} from '@/utils/partnerError'
import {catalogIdentity,catalogKey} from './catalogPresentation'
import {moqScopeLabel} from '@/utils/partnerPrice'
const props=defineProps<{items:CatalogStyle[];supplierCode:string}>(),emit=defineEmits<{close:[];saved:[]}>()
const modes=ref<Record<string,'new'|'existing'>>(Object.fromEntries(props.items.map(row=>[catalogKey(row),'new']))),linked=ref<Record<string,number|undefined>>({}),choices=ref<CatalogCodeOption[]>([]),keyword=ref(''),page=ref(1),total=ref(0),loading=ref(false),busy=ref(false),error=ref(''),reason=ref(''),preview=ref<CatalogIdentityPreview>(),requestId=ref(newRequestId())
let generation=0
const payload=computed(()=>({supplierCode:props.supplierCode,items:props.items.map(row=>({...catalogIdentity(row),...(row.catalogStyleId?{catalogStyleId:row.catalogStyleId}:modes.value[catalogKey(row)]==='existing'?{catalogStyleId:linked.value[catalogKey(row)]}:{})}))}))
const valid=computed(()=>props.items.length>0&&props.items.every(row=>row.catalogStyleId||modes.value[catalogKey(row)]!=='existing'||!!linked.value[catalogKey(row)]))
watch(payload,()=>{preview.value=undefined;requestId.value=newRequestId()},{deep:true})
async function search(reset=false){if(reset)page.value=1;const seq=++generation;loading.value=true;error.value='';try{const result=await catalogStyleIdentities({supplierCode:props.supplierCode,keyword:keyword.value.trim(),page:page.value,size:20});if(seq!==generation)return;choices.value=result.content;total.value=result.totalElements}catch(e){if(seq===generation)error.value=partnerError(e)}finally{if(seq===generation)loading.value=false}}
async function check(){if(!valid.value||busy.value)return;const signature=JSON.stringify(payload.value);busy.value=true;error.value='';try{const result=await previewCatalogIdentities(payload.value);if(signature===JSON.stringify(payload.value))preview.value=result}catch(e){error.value=partnerError(e)}finally{busy.value=false}}
async function save(){if(!preview.value?.canConfirm||!reason.value.trim()||busy.value)return;busy.value=true;error.value='';try{await saveCatalogIdentities({...payload.value,reason:reason.value.trim(),requestId:requestId.value,previewToken:preview.value.previewToken});emit('saved')}catch(e){error.value=partnerError(e)}finally{busy.value=false}}
async function close(){if(busy.value)return;if(preview.value||reason.value.trim()||Object.values(linked.value).some(Boolean))try{await ElMessageBox.confirm('放弃本次未保存的款式号关联？','保留本次核对',{confirmButtonText:'放弃并关闭',cancelButtonText:'继续核对',closeOnClickModal:false})}catch{return}emit('close')}
const action=(value:string)=>({new:'保存时系统分配',link:'关联已有款式号',unchanged:'保留现有身份'} as Record<string,string>)[value]||value
onBeforeUnmount(()=>{generation++})
</script>
<template><el-dialog :model-value="true" title="款式号与报价字段核对" width="min(960px,96vw)" top="20px" class="catalog-identity-dialog" append-to-body :close-on-click-modal="false" :before-close="close"><div class="identity-content"><p>保留原行、原件、图片及修订；本次只建立独立款式映射和经确认的字段规范化。不创建产品或样品。</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><article v-for="row in items" :key="catalogKey(row)" class="identity-row"><strong>{{row.name}}</strong><span v-if="row.catalogStyleId">{{row.catalogStyleLabel||row.catalogStyleCode}} · 保留</span><template v-else><el-radio-group v-model="modes[catalogKey(row)]" @change="$event==='existing'&&search(true)"><el-radio value="new">独立款式（保存时分配）</el-radio><el-radio value="existing">明确关联已有同款</el-radio></el-radio-group><el-select v-if="modes[catalogKey(row)]==='existing'" v-model="linked[catalogKey(row)]" placeholder="从下方已核实款式号中选择" clearable><el-option v-for="option in choices" :key="option.id" :value="option.id" :label="(option.label||option.code)+' · '+option.name+' · '+option.supplierName"/></el-select></template></article><details><summary @click="!choices.length&&search()">查找本供应商已有款式号</summary><form class="identity-search" @submit.prevent="search(true)"><el-input v-model="keyword" clearable placeholder="款式号／名称"/><el-button native-type="submit" :loading="loading">查询</el-button></form><p v-for="option in choices" :key="option.id">{{option.label||option.code}} · {{option.name}} · {{option.supplierName}}</p><el-pagination :current-page="page" :total="total" :page-size="20" :pager-count="5" layout="prev,pager,next" @current-change="page=$event;search()"/></details><section v-if="preview" class="identity-preview"><p v-for="message in preview.messages" :key="message">{{message}}</p><article v-for="item in preview.items" :key="item.rowId"><strong>{{item.name}} · {{item.catalogStyleLabel||item.catalogStyleCode||action(item.action)}}</strong><dl><div><dt>币种</dt><dd>{{item.beforeFields.currency||'原值未注明'}} → {{item.normalizedFields.currency||'待核对'}}</dd></div><div><dt>计价单位</dt><dd>{{item.normalizedFields.priceUnit||'未提供'}}</dd></div><div><dt>起订数量</dt><dd>{{item.normalizedFields.moqQuantity??'未确认'}}</dd></div><div><dt>起订单位</dt><dd>{{item.normalizedFields.moqUnit||'未确认'}}</dd></div><div><dt>起订口径</dt><dd>{{moqScopeLabel(String(item.normalizedFields.moqScope||''))}}</dd></div></dl><p v-for="message in item.messages" :key="message">{{message}}</p></article></section><el-form-item label="本次核对原因 *"><el-input v-model="reason" type="textarea" autosize/></el-form-item></div><template #footer><el-button :disabled="busy" @click="close">返回</el-button><el-button :disabled="!valid||busy" :loading="busy" @click="check">预览差异</el-button><el-button type="primary" :disabled="!preview?.canConfirm||!reason.trim()||busy" :loading="busy" @click="save">确认映射与字段</el-button></template></el-dialog></template>
<style scoped>:global(.catalog-identity-dialog){display:flex;flex-direction:column;max-height:calc(100dvh - 40px);margin-bottom:20px}:global(.catalog-identity-dialog>.el-dialog__body){min-height:0;overflow-y:auto}:global(.catalog-identity-dialog>.el-dialog__footer){display:flex;justify-content:flex-end;gap:7px;flex-wrap:wrap}.identity-content{font-size:13px;line-height:1.6;min-width:0}.identity-content p{overflow-wrap:anywhere}.identity-row{display:flex;flex-direction:column;gap:6px;padding:9px 0;border-bottom:1px solid var(--el-border-color-lighter)}.identity-search{display:flex;gap:7px}.identity-search>.el-input{flex:1;min-width:0}.identity-preview article{border:1px solid var(--el-border-color-lighter);padding:8px;margin:8px 0;border-radius:5px}.identity-preview dl{display:flex;gap:5px 16px;flex-wrap:wrap}.identity-preview dl>div{display:flex;gap:5px;min-width:0;overflow-wrap:anywhere}.identity-preview dd{margin:0}.identity-preview dt{color:var(--el-text-color-secondary)}.identity-content :deep(.el-radio){height:auto;white-space:normal;margin-right:12px}.identity-content :deep(.el-radio__label){white-space:normal;overflow-wrap:anywhere}.identity-content :deep(.el-radio-group){display:flex;flex-wrap:wrap;gap:7px}.identity-content :deep(.el-select){width:100%}</style>
